public HistorySynchronizer(final GameData data, final IGame game) {
  if (game.getData() == data) {
    throw new IllegalStateException("You dont need a history synchronizer to synchronize game data that is " + "managed by an IGame");
  }
  gameData = data;
  gameData.forceChangesOnlyInSwingEventThread();
  data.acquireReadLock();
  try {
    currentRound = data.getSequence().getRound();
  } catch (NullPointerException e) {
    // Handle the exception, e.g., log it or set a default value for currentRound
    currentRound = 0; // or handle it as needed
  } finally {
    data.releaseReadLock();
  }
  this.game = game;
  this.game.getMessengers().registerChannelSubscriber(gameModifiedChannelListener, IGame.GAME_MODIFICATION_CHANNEL);
}
